--
-- Table structure for table `phone_active_info`
--

DROP TABLE IF EXISTS `phone_active_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `phone_active_info` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `phone_type` varchar(10) DEFAULT NULL COMMENT '手机型号编码',
  `sn` varchar(64) DEFAULT NULL COMMENT 'sn号',
  `imei1` varchar(32) DEFAULT NULL COMMENT 'imei1号',
  `imei2` varchar(32) DEFAULT NULL COMMENT 'imei2号',
  `model` varchar(64) DEFAULT NULL COMMENT '型号',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `create_by` varchar(64) DEFAULT NULL COMMENT '创建人',
  `nick_name` varchar(30) DEFAULT NULL COMMENT '创建人昵称',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `update_by` varchar(64) DEFAULT NULL COMMENT '更新人',
  `info_id` bigint(20) DEFAULT NULL COMMENT '留资人ID，关联 leave_information.id',
  `store_id` bigint(20) DEFAULT NULL COMMENT '所属门店ID，关联 sys_dept.dept_id',
  `skip_api_call` tinyint(1) DEFAULT '0' COMMENT '是否跳过06 API查询：0-正常查询 1-无旧手机跳过',
  `channel` varchar(10) DEFAULT NULL COMMENT '订单渠道：自有/亚丁（导入时直接指定；历史数据为空时前端按规则推导）',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标志（0=正常 2=测试数据/已逻辑删除）',
  `old_phone_status` tinyint(1) DEFAULT NULL COMMENT '旧手机状态：0-无旧手机 1-损坏/丢失',
  `old_phone_usage_months` int(11) DEFAULT NULL COMMENT '旧手机已使用月数',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_imei1` (`imei1`) USING BTREE,
  KEY `idx_model` (`model`) USING BTREE,
  KEY `idx_sn` (`sn`) USING BTREE,
  KEY `idx_info_id` (`info_id`),
  KEY `idx_store_id` (`store_id`)
) ENGINE=InnoDB AUTO_INCREMENT=444 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC COMMENT='手机激活信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `phone_active_info`
--

LOCK TABLES `phone_active_info` WRITE;
/*!40000 ALTER TABLE `phone_active_info` DISABLE KEYS */;
